#!/usr/bin/env node
/* JS parity test — the sandbox ports vs the REAL JouleX modules.
 *
 * Ground truth: tests/expected.json, generated by tests/gen_expected.py
 * from joulex.lmsr, joulex.attestation.canonical_bytes, hashlib, and
 * joulex.orchestrator.run_simulation. Run: node tests/parity.cjs
 * (from ~/workspace/joulex/sandbox). Exit non-zero on any mismatch.
 */
"use strict";

const fs = require("fs");
const path = require("path");
const crypto = require("crypto");

const LMSR = require("../lmsr.js");
const Hash = require("../sha256.js");
const Orch = require("../scheduler.js");

const expected = JSON.parse(fs.readFileSync(path.join(__dirname, "expected.json"), "utf-8"));
const data = JSON.parse(fs.readFileSync(path.join(__dirname, "..", "data.json"), "utf-8"));

let failures = 0;
function check(name, ok, detail) {
  if (!ok) {
    failures++;
    console.log("FAIL: " + name + (detail ? " — " + detail : ""));
  }
}
function close(a, b, tol) { return Math.abs(a - b) <= tol; }

// --- 1. SHA-256 vs Node crypto (sanity: our implementation itself) ---
["", "abc", "joulex", "The quick brown fox jumps over the lazy dog",
 "héllo wörld — AESO", "x".repeat(1000)].forEach((s) => {
  const want = crypto.createHash("sha256").update(s, "utf8").digest("hex");
  check("sha256(" + JSON.stringify(s.slice(0, 20)) + ")", Hash.sha256Hex(s) === want,
    "got " + Hash.sha256Hex(s) + " want " + want);
});

// --- 2. Canonical JSON + SHA-256 vs Python ---------------------------
expected.hash.forEach((c, i) => {
  const got = Hash.canonical(c.payload);
  check("canonical case " + i, got === c.canonical,
    "got " + got + " want " + c.canonical);
  check("sha256Canonical case " + i, Hash.sha256Canonical(c.payload) === c.sha256);
});

// --- 3. LMSR vs Python (300 randomized cases) -------------------------
let worstCostErr = 0, worstPriceErr = 0;
expected.lmsr.forEach((c, i) => {
  const cost = LMSR.costFunctionMulti(c.q, c.b);
  const prices = LMSR.pricesMulti(c.q, c.b);
  const tc = LMSR.tradeCostMulti(c.q, c.b, c.index, c.shares);
  worstCostErr = Math.max(worstCostErr, Math.abs(cost - c.cost_before));
  c.prices_before.forEach((p, j) => {
    worstPriceErr = Math.max(worstPriceErr, Math.abs(prices[j] - p));
  });
  check("lmsr cost case " + i, close(cost, c.cost_before, 1e-9),
    "got " + cost + " want " + c.cost_before);
  check("lmsr trade_cost case " + i, tc === c.trade_cost,
    "got " + tc + " want " + c.trade_cost);
  prices.forEach((p, j) => {
    check("lmsr price case " + i + "/" + j, close(p, c.prices_before[j], 1e-12),
      "got " + p + " want " + c.prices_before[j]);
  });
  // Round-trip: buy then exact reverse sell returns the cost exactly.
  const q2 = LMSR.applyTradeMulti(c.q, c.index, c.shares);
  const back = LMSR.tradeCostMulti(q2, c.b, c.index, -c.shares);
  check("lmsr round-trip case " + i, back === -tc,
    "sell-back " + back + " vs -" + tc);
});
console.log("LMSR: 300 cases, worst cost err " + worstCostErr.toExponential(2) +
  ", worst price err " + worstPriceErr.toExponential(2));

// --- 4. Orchestrator vs Python run_simulation -------------------------
const prices = data.synthetic.prices.map((p) => [p.timestamp, p.price]);
const jobs = data.jobs;
const sim = Orch.runSimulation(prices, jobs, { sourceLabel: "SYNTHETIC" });
const want = expected.orchestrator;
Object.keys(want.costs).forEach((k) => {
  check("orch cost " + k, close(sim.costs[k], want.costs[k], 1e-6),
    "got " + sim.costs[k] + " want " + want.costs[k]);
});
Object.keys(want.improvement_pct).forEach((k) => {
  check("orch improvement " + k, close(sim.improvement_pct[k], want.improvement_pct[k], 0.01),
    "got " + sim.improvement_pct[k] + " want " + want.improvement_pct[k]);
});
Object.keys(want.sla_pct).forEach((k) => {
  check("orch sla " + k, close(sim.sla_pct[k], want.sla_pct[k], 1e-9),
    "got " + sim.sla_pct[k] + " want " + want.sla_pct[k]);
});
Object.keys(want.allocations).forEach((name) => {
  const got = sim.allocations[name], w = want.allocations[name];
  const same = JSON.stringify(got) === JSON.stringify(w);
  check("orch allocation " + name, same,
    same ? "" : "allocation differs from Python");
});
console.log("Orchestrator: verdict " + sim.verdict + " (Python, unaudited: " +
  want.verdict + ") — improvement vs greedy " + sim.improvement_pct.vs_greedy +
  "%, SLA " + sim.sla_pct.orchestrator + "%");

if (failures > 0) {
  console.log("PARITY FAILED: " + failures + " mismatch(es)");
  process.exit(1);
}
console.log("PARITY OK: LMSR 300 cases exact, canonical/SHA-256 exact, " +
  "orchestrator costs/allocations match Python.");
